(function() {
    console.log('[stackinputhelper] main.min.js loaded');

    const config = Object.assign({
        apiurl: 'http://localhost:3001/recognize',
        apitoken: '',
        uploadbtn: 'Upload math image',
        uploading: 'Recognizing...',
        recognizefailed: 'Recognition failed.'
    }, window.STACKINPUTHELPER_CONFIG || {});

    console.log('[stackinputhelper] config =', config);

    const findAnswerBox = () => {
        const selectors = [
            'input[type="text"]',
            'input:not([type])'
        ];

        for (const selector of selectors) {
            const candidates = Array.from(document.querySelectorAll(selector));
            const visible = candidates.find(el => el.offsetParent !== null);
            if (visible) {
                console.log('[stackinputhelper] found input by selector:', selector, visible);
                return visible;
            }
        }

        console.warn('[stackinputhelper] no visible input found');
        return null;
    };

    const createHiddenFileInput = () => {
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'image/*';
        fileInput.style.display = 'none';
        document.body.appendChild(fileInput);
        return fileInput;
    };

    const setAnswerValue = (input, value) => {
        input.focus();
        input.value = value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    };

    const callRecognizer = async (file) => {
        const apiurl = config.apiurl || 'http://localhost:3001/recognize';
        console.log('[stackinputhelper] using apiurl =', apiurl);

        const formData = new FormData();
        formData.append('image', file);

        const headers = {};
        if (config.apitoken) {
            headers['Authorization'] = 'Bearer ' + config.apitoken;
        }

        const response = await fetch(apiurl, {
            method: 'POST',
            body: formData,
            headers
        });

        if (!response.ok) {
            throw new Error('HTTP ' + response.status);
        }

        return await response.json();
    };

    const createResultPanel = () => {
        const panel = document.createElement('div');
        panel.style.marginTop = '8px';
        panel.style.padding = '8px';
        panel.style.border = '1px solid #ddd';
        panel.style.background = '#fafafa';
        panel.style.fontSize = '13px';
        panel.style.lineHeight = '1.5';
        panel.style.display = 'none';

        const rawTitle = document.createElement('div');
        rawTitle.textContent = 'OCR raw result:';
        rawTitle.style.fontWeight = 'bold';

        const rawValue = document.createElement('div');
        rawValue.style.marginBottom = '8px';
        rawValue.style.whiteSpace = 'pre-wrap';
        rawValue.style.wordBreak = 'break-word';

        const stackTitle = document.createElement('div');
        stackTitle.textContent = 'STACK result:';
        stackTitle.style.fontWeight = 'bold';

        const stackValue = document.createElement('div');
        stackValue.style.whiteSpace = 'pre-wrap';
        stackValue.style.wordBreak = 'break-word';

        panel.appendChild(rawTitle);
        panel.appendChild(rawValue);
        panel.appendChild(stackTitle);
        panel.appendChild(stackValue);

        panel._rawValue = rawValue;
        panel._stackValue = stackValue;

        return panel;
    };

    const updateResultPanel = (panel, raw, stack) => {
        if (!panel) {
            return;
        }
        panel.style.display = 'block';
        panel._rawValue.textContent = raw || '(empty)';
        panel._stackValue.textContent = stack || '(empty)';
    };

    const toDisplayableString = (value) => {
        if (typeof value === 'string') {
            return value;
        }
        if (value == null) {
            return '';
        }
        try {
            return JSON.stringify(value, null, 2);
        } catch (e) {
            return String(value);
        }
    };

    const pickRawResult = (result) => {
        // OCR 原始展示：优先 LaTeX
        if (typeof result.latex === 'string' && result.latex.trim()) {
            return result.latex.trim();
        }
        if (typeof result.latex_styled === 'string' && result.latex_styled.trim()) {
            return result.latex_styled.trim();
        }
        if (typeof result.raw === 'string' && result.raw.trim()) {
            return result.raw.trim();
        }
        return toDisplayableString(result.raw);
    };

    const pickStackResult = (result) => {
        // STACK 用结果：优先 stack/text/normalized，绝对不要优先 latex
        if (typeof result.stack === 'string' && result.stack.trim()) {
            return result.stack.trim();
        }
        if (typeof result.text === 'string' && result.text.trim()) {
            return result.text.trim();
        }
        if (typeof result.normalized === 'string' && result.normalized.trim()) {
            return result.normalized.trim();
        }
        if (typeof result.converted === 'string' && result.converted.trim()) {
            return result.converted.trim();
        }
        return '';
    };

    const attachButton = (answerBox) => {
        if (!answerBox) {
            return;
        }

        if (answerBox.dataset.stackinputhelperBound === '1') {
            console.log('[stackinputhelper] already bound');
            return;
        }

        answerBox.dataset.stackinputhelperBound = '1';

        const fileInput = createHiddenFileInput();
        const resultPanel = createResultPanel();

        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = config.uploadbtn || 'Upload math image';
        button.style.marginLeft = '8px';
        button.style.padding = '4px 8px';
        button.style.border = '1px solid #999';
        button.style.background = '#f5f5f5';
        button.style.cursor = 'pointer';

        button.addEventListener('click', function() {
            fileInput.value = '';
            fileInput.click();
        });

        fileInput.addEventListener('change', async function() {
            const file = fileInput.files && fileInput.files[0];
            if (!file) {
                return;
            }

            const oldText = button.textContent;
            button.disabled = true;
            button.textContent = config.uploading || 'Recognizing...';

            try {
                const result = await callRecognizer(file);
                console.log('[stackinputhelper] recognizer result =', result);

                const raw = pickRawResult(result);
                const stack = pickStackResult(result);

                if (!stack) {
                    throw new Error('Empty STACK result');
                }

                updateResultPanel(resultPanel, raw, stack);
                setAnswerValue(answerBox, stack);
            } catch (error) {
                console.error('[stackinputhelper] recognition failed:', error);
                alert((config.recognizefailed || 'Recognition failed.') + '\n' + error.message);
            } finally {
                button.disabled = false;
                button.textContent = oldText;
            }
        });

        answerBox.insertAdjacentElement('afterend', button);
        button.insertAdjacentElement('afterend', resultPanel);

        console.log('[stackinputhelper] button inserted');
    };

    const run = () => {
        console.log('[stackinputhelper] run start');
        const answerBox = findAnswerBox();
        attachButton(answerBox);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', run);
    } else {
        run();
    }
})();